<template>
  <div class="ma-root">
    <!-- ── HERO ──────────────────────────────────────────────────────── -->
    <header class="ma-hero">
      <div class="ma-hero__bg">
        <div class="ma-hero__grid"></div>
        <div class="ma-hero__glow"></div>
      </div>
      <div class="ma-hero__inner">
        <v-btn text dark small class="mb-5" @click="goBack">
          <v-icon left small>mdi-arrow-left</v-icon>Dashboard
        </v-btn>
        <h1 class="ma-hero__title">My Applications</h1>
        <p class="ma-hero__sub">
          Track all positions you have applied for and their current status.
        </p>
      </div>
    </header>

    <!-- ── TOOLBAR ────────────────────────────────────────────────────── -->
    <div class="ma-toolbar">
      <v-text-field
        v-model="search"
        placeholder="Search by position title…"
        dense outlined hide-details clearable
        prepend-inner-icon="mdi-magnify"
        style="flex:1; min-width:200px;"
        @input="onSearchInput"
        @click:clear="clearSearch"
      />
      <v-select
        v-model="statusFilter"
        :items="statusOptions"
        item-text="text"
        item-value="value"
        dense outlined hide-details
        style="min-width:170px;"
        @change="resetAndLoad"
      />
      <v-select
        v-model="count"
        :items="[{text:'10 / page', value:10},{text:'20 / page', value:20},{text:'50 / page', value:50}]"
        item-text="text"
        item-value="value"
        dense outlined hide-details
        style="width:120px;"
        @change="onCountChange"
      />
    </div>

    <!-- ── LOADING ────────────────────────────────────────────────────── -->
    <div v-if="loading" class="d-flex flex-column align-center justify-center pa-16" style="gap:12px;">
      <v-progress-circular size="36" width="3" indeterminate color="primary" />
      <span class="body-2 grey--text">Loading your applications…</span>
    </div>

    <!-- ── NO RESULTS ─────────────────────────────────────────────────── -->
    <div v-else-if="applications.length === 0" class="d-flex flex-column align-center pa-16 text-center" style="gap:12px;">
      <v-icon size="52" color="grey lighten-2">mdi-file-document-outline</v-icon>
      <p class="subtitle-2 grey--text text--darken-1 ma-0">No applications found</p>
      <p class="caption grey--text ma-0">
        {{ search || statusFilter ? "Try adjusting your filters." : "You have not submitted any applications yet." }}
      </p>
      <v-btn color="primary" depressed @click="goToPositions">
        <v-icon left small>mdi-briefcase-search-outline</v-icon>Browse Open Positions
      </v-btn>
    </div>

    <!-- ── APPLICATION LIST ───────────────────────────────────────────── -->
    <main v-else class="ma-list">
      <article
        v-for="app in applications"
        :key="app.id"
        class="ma-card"
        @click="viewApplication(app)"
      >
        <!-- Top row: title + status chip -->
        <div class="ma-card__header">
          <div class="ma-card__title">
            {{ app.positionTitle || "Position" }}
          </div>
          <span class="ma-status" :class="'ma-status--' + displayStatusCode(app)">
            <span class="ma-status__dot"></span>
            {{ displayStatusLabel(app) }}
          </span>
        </div>

        <!-- Description excerpt -->
        <p v-if="app.description" class="ma-card__desc">
          {{ app.description }}
        </p>

        <!-- Meta row -->
        <div class="ma-card__meta">
          <span class="ma-meta-item" v-if="app.vacancies">
            <v-icon size="13" color="#94a3b8">mdi-account-group-outline</v-icon>
            {{ app.vacancies }} vacanc{{ app.vacancies === 1 ? "y" : "ies" }}
          </span>
          <span class="ma-meta-item" v-if="app.advertOpenDate">
            <v-icon size="13" color="#94a3b8">mdi-calendar-start</v-icon>
            Opened {{ fmtDate(app.advertOpenDate) }}
          </span>
          <span class="ma-meta-item" v-if="app.advertCloseDate">
            <v-icon size="13" color="#94a3b8">mdi-clock-outline</v-icon>
            Closes {{ fmtDate(app.advertCloseDate) }}
          </span>
          <span class="ma-meta-item">
            <v-icon size="13" color="#94a3b8">mdi-file-document-outline</v-icon>
            Applied {{ fmtDate(app.applicationDate) }}
          </span>
        </div>

        <!-- Footer: advert posted date + arrow -->
        <div class="ma-card__footer">
          <span v-if="app.postedDate" class="ma-card__posted">Posted {{ fmtDate(app.postedDate) }}</span>
          <span class="ma-card__footer-spacer"></span>
          <span class="ma-card__cta">
            View Details
            <v-icon size="14" color="#0f2d5e">mdi-chevron-right</v-icon>
          </span>
        </div>
      </article>
    </main>

    <!-- ── PAGINATION ─────────────────────────────────────────────────── -->
    <div v-if="!loading && total > count" class="d-flex align-center justify-center flex-wrap py-6 px-4" style="gap:8px;">
      <v-pagination v-model="page" :length="totalPages" :total-visible="7" color="primary" @input="load" />
      <span class="caption grey--text ml-2">
        {{ (page - 1) * count + 1 }}–{{ Math.min(page * count, total) }} of {{ total }}
      </span>
    </div>
  </div>
</template>

<script>
export default {
  name: "MyApplications",
  props: ["queries"],

  data() {
    return {
      applications: [],
      loading: false,
      total: 0,
      page: 1,
      count: 10,
      search: "",
      statusFilter: "",
      searchTimer: null,
      statusOptions: [
        { text: "All Statuses",     value: "" },
        { text: "Under Review",     value: "underreview" },
        { text: "Shortlisted",      value: "shortlisted" },
        { text: "Not Shortlisted",  value: "notshortlisted" },
        { text: "Interviewed",      value: "interviewed" },
        { text: "Recommended",      value: "recommended" },
        { text: "Not Recommended",  value: "notrecommended" },
        { text: "Offer Made",       value: "offered" },
        { text: "Offer Accepted",   value: "accepted" },
        { text: "Offer Declined",   value: "declined" },
        { text: "Withdrawn",        value: "withdrawn" },
      ],
    };
  },

  computed: {
    userResource() {
      return this.$store.state?.user?.obj?.resource;
    },

    subjectRef() {
      const exts = this.userResource?.extension || [];

      // External applicant (non-staff)
      const applicantExt = exts.find(
        (e) =>
          e.url ===
          "http://ihris.org/fhir/StructureDefinition/ihris-external-applicant-reference",
      );
      if (applicantExt?.valueReference?.reference) {
        return {
          type: "applicant",
          id: applicantExt.valueReference.reference.split("/").pop(),
        };
      }

      // Staff — use practitioner reference
      const practExt = exts.find(
        (e) =>
          e.url ===
          "http://ihris.org/fhir/StructureDefinition/ihris-practitioner-reference",
      );
      if (practExt?.valueReference?.reference) {
        return {
          type: "practitioner",
          id: practExt.valueReference.reference.split("/").pop(),
        };
      }

      return null;
    },

    totalPages() {
      return Math.max(1, Math.ceil(this.total / this.count));
    },

  },

  mounted() {
    this.load();
  },

  methods: {
    async load() {
      if (!this.subjectRef) {
        this.applications = [];
        this.total = 0;
        return;
      }

      this.loading = true;
      try {
        const offset = (this.page - 1) * this.count;
        const params = new URLSearchParams({
          _count: this.count,
          _getpagesoffset: offset,
        });

        if (this.subjectRef.type === "applicant") {
          params.set("applicantid", this.subjectRef.id);
        } else {
          params.set("practitionerid", this.subjectRef.id);
        }

        const res = await fetch(`/site/position/applied-positions?${params}`);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();

        this.total = data.total ?? 0;
        this.applications = data.applications ?? [];
      } catch (err) {
        console.error("my-applications load error", err);
        this.applications = [];
        this.total = 0;
      } finally {
        this.loading = false;
      }
    },

    // Applicants only see their real application status once hiring has
    // been closed for the advertisement — while hiring is still ongoing,
    // everything reads as "Under Review" regardless of internal status
    // (shortlisted/offered/etc.) to avoid tipping off outcomes early.
    displayStatusCode(app) {
      return app.hiringClosed ? app.statusCode || "underreview" : "underreview";
    },
    displayStatusLabel(app) {
      return app.hiringClosed
        ? app.statusDisplay || "Under Review"
        : "Under Review";
    },

    fmtDate(val) {
      if (!val) return "—";
      try {
        const [y, m, d] = val.split("T")[0].split("-");
        const months = [
          "Jan",
          "Feb",
          "Mar",
          "Apr",
          "May",
          "Jun",
          "Jul",
          "Aug",
          "Sep",
          "Oct",
          "Nov",
          "Dec",
        ];
        if (!m) return y;
        if (!d) return `${months[parseInt(m, 10) - 1]} ${y}`;
        return `${parseInt(d, 10)} ${months[parseInt(m, 10) - 1]} ${y}`;
      } catch {
        return val;
      }
    },

    onSearchInput() {
      clearTimeout(this.searchTimer);
      this.searchTimer = setTimeout(() => this.resetAndLoad(), 400);
    },

    clearSearch() {
      this.search = "";
      this.resetAndLoad();
    },

    resetAndLoad() {
      this.page = 1;
      this.load();
    },

    onCountChange() {
      this.page = 1;
      this.load();
    },

    viewApplication(app) {
      this.$router.push({
        path: "/custom/application-view",
        query: {
          path: "/lesotho/components/recruitment",
          applicationId: app.id,
        },
      });
    },

    goToPositions() {
      this.$router.push({
        path: "/custom/advertised-positions",
        query: { path: "/lesotho/components/recruitment" },
      });
    },

    goBack() {
      this.$router.push({
        path: "/custom/applicant-dashboard",
        query: { path: "/lesotho/components/recruitment" },
      });
    },
  },
};
</script>

